function documentTemplateRequests(messages) {
  const content = [...messages].reverse().find((message) => message.role === "user")?.content ?? "";
  const text = content.replace(/```[\s\S]*?(?:```|$)/g, "").replace(/^\s*>.*$/gm, "").replace(/[“「][\s\S]*?[”」]|"[^"\n]*"/g, "").replace(/[《》\s]/g, "");
  const clauses = text.split(/[，,。.!！?？;；\n]/).filter((clause) => !/(?:不要|不用|无需|别|暂不|先不|如何|怎么|为什么|只是|只问|取消)/.test(clause) && /(?:生成|导出|制作|出一份)/.test(clause));
  return templateCatalog.filter((template) => !template.excludedReason && clauses.some((clause) => clause.includes(template.name))).map((template) => template.id);
}
