// src-ui/src/ai/structureReverseIntent.ts
function structureReverseIntent(messages) {
  const index = messages.reduce((last, item, i) => item.role === "user" ? i : last, -1);
  const raw = messages[index]?.content ?? "";
  const text = raw.replace(/```[\s\S]*?(?:```|$)|^\s*>.*$/gm, "").replace(/[“「][\s\S]*?[”」]|"[^"\n]*"/g, "");
  const metricType = /(?:NPV\s*率|净现值率)/i.test(text) ? "npv_rate" : "margin";
  const affirmativeClauses = text.split(/[，。！？;；\n]/).filter((clause) => !/(?:不要|不用|无需|暂不|先不|取消|别)/.test(clause) && !/(?:刚才|上次|上一轮|此前|之前|昨天)/.test(clause));
  const requested = affirmativeClauses.some((clause) => !/(?:甄选费|限价).{0,6}反算/.test(clause) && (/(?:结构反算|智能反算)/.test(clause) || /(?:利润率|净现值率|NPV\s*率)/i.test(clause) && /(?:做到|达到|调整为|调整到|设为|提高到|降到|反算)/.test(clause)));
  const targetText = affirmativeClauses.filter((clause) => /(?:目标|利润率|净现值率|NPV\s*率|做到|达到|调整为|调整到|设为|提高到|降到)/i.test(clause)).join("\uFF0C");
  const values = [...targetText.matchAll(/(-?\d+(?:\.\d+)?)\s*[%％]/g)];
  return {
    requested,
    key: `${index}:${raw}`,
    metricType,
    targetPercent: requested && values.length === 1 ? values[0][1] : "",
    scenario: /甄选后|post_selection/.test(text) ? "post_selection" : /甄选前|pre_selection/.test(text) ? "pre_selection" : ""
  };
}
