var task = new RegExp(`^(?:${timing}${request}|${request}${timing})${action}(?:\u4E00\u4E0B|\u4E00\u4EFD|\u4E00\u5F20|\u8FD9\u4EFD|\u8FD9\u5F20|\u8FD9\u4E2A|\u672C\u9879\u76EE\u7684|\u9879\u76EE\u7684|\u4E00\u4EFD\u672C\u9879\u76EE\u7684)?${form}`);
var namedTask = new RegExp(`^(?:\u8FD9\u4E2A|\u8FD9\u4EFD|\u8FD9\u5F20)?${form}(?:\u7684\u5185\u5BB9)?(?:${request}${timing})${action}`);
function isDemandFormRequest(content) {
  const text = content.replace(/```[\s\S]*?(?:```|$)/g, "").replace(/^\s*>.*$/gm, "").replace(new RegExp(`[\u201C\u300C"](${form})[\u201D\u300D"]`, "g"), "$1").replace(/[“「][\s\S]*?[”」]|"[^"\n]*"/g, "").replace(/[《》\t ]/g, "");
  if (/(?:不要|不用|无需|别|暂不|先不).{0,12}(?:上传|补图|图片|附件|提醒)/.test(text)) return false;
  return text.split(/[，,。.!！?？;；\n]/).some((clause) => !/(?:如何|怎么|怎样|什么|会不会|能不能|是否|为什么|只是|只想|只问)/.test(clause.replace(/^(?:能不能|能否)/, "")) && (task.test(clause) || namedTask.test(clause)));
}
function demandImageCompletionPrompt(requested) {
  return requested ? "The current user turn explicitly requests demand-form filling or generation. The chat can show labeled upload cards for missing demand-template images after checking saved state. Only guide the user to these cards when images are actually missing; never claim a file was saved or generated by this invitation." : "No demand-image upload invitation is active for this turn. Binding a project, general conversation, read-only template questions and ordinary chat image attachments do not request form filling or generation. Do not proactively ask for demand-template images or claim upload cards are visible. If the user explicitly wants to fill or generate the demand form, they can say so in the next message. Answer their current question without adding an upload reminder.";
}

// src-ui/src/ai/templateImageIntent.ts
function wantsTemplateImages(content) {
  const text = content.replace(/```[\s\S]*?(?:```|$)/g, "").replace(/^\s*>.*$/gm, "").replace(/[“「"][\s\S]*?[”」"]/g, "");
  if (/(?:不要|不用|无需|别|暂不|先不|不想).{0,12}(?:图片|附件|展示|替换|修改)/.test(text)) return false;
  return text.split(/[。！？\n]/).some((part) => !/(?:为什么|如何|怎么|昨天|之前|如果|客户说|是什么意思)/.test(part) && /(?:展示|显示|查看|看看|调出|打开|替换|更换|修改|换掉|给我看)/.test(part) && /(?:图片|附件[12一二]?|客户确认材料|公示截图|asset_[a-z0-9]+)/i.test(part));
}
function templateImagePrompt(requested) {
  return requested ? "The user explicitly requests saved project images. The application shows a project image card using trusted session binding. It lists saved demand-form attachments including existing images. Guide the user to view the card, select an exact image, and choose a replacement with before/after preview, then click Confirm replacement. No write occurs until that click. This card only views/replaces existing images; if the list is empty it has no Add/upload action. For missing attachments, explicitly request demand-form filling/generation to use the separate missing-image upload card, or upload on the template page. Uploading a new file elsewhere appends; it does not replace an existing image. The card can attach a selected saved image to the composer for visual analysis; only claim to see its contents when image bytes are actually sent with the user message. Do not call bash/glob/read_image or guess asset paths. No model image editing service is connected: describe crop/text-edit suggestions honestly, do not claim to have edited pixels." : "Saved image metadata is not image content. For an explicit request to view/replace saved images, the user can open the Project images button in chat or ask to show existing images. That card supports selecting a demand-form attachment, previewing a replacement and confirming it. Do not use filesystem tools or guess asset paths to retrieve images. Ordinary chat attachments are not automatically saved to templates; uploading normally appends, not replaces. No image pixel editing service is connected.";
}

// src-ui/src/ai/webui/businessPresentation.ts
function businessPresentation(messages) {
  const user = [...messages].reverse().find((message) => message.role === "user")?.content ?? "";
  return {
    documents: documentTemplateRequests(messages),
    lists: templateListIntent(messages),
    proposal: techProposal(messages),
    reverse: structureReverseIntent(messages),
    demandImages: isDemandFormRequest(user),
    savedImages: wantsTemplateImages(user)
  };
}
